  if (m) return `${tr(m[1])} ${m[2]}${m[3] ? (UNIT_FR[m[3].trim()] ? ` ${UNIT_FR[m[3].trim()]}` : m[3]) : ''} (${{ first: 'premier', baseline: 'référence', expected: 'attendu' }[m[4]]} ${m[5]})${m[6] ? `, ${m[6]} fois de suite` : ''}`;
