import { PHRASES_FR } from './i18n.js';

export function frText(english) {
  const t = english.replace(/\s+/g, ' ').trim();
  if (!t) return null;
  if (Object.prototype.hasOwnProperty.call(TEXT_FR, t)) return TEXT_FR[t];
  if (Object.prototype.hasOwnProperty.call(PHRASES_FR, t)) return PHRASES_FR[t];
  for (const [re, fn] of PATTERNS_FR) {
    const m = t.match(re);
    if (m) { const out = fn(m); if (out != null) return out; }
  }
  return null;
}

// English originals, so switching back to English restores the page exactly.
const ORIG = new WeakMap();
const ATTRS = ['aria-label', 'placeholder', 'title', 'data-label'];
const skip = (el) => !el || el.closest('script,style,textarea,[data-i18n],[translate="no"],.notranslate');

function translateText(node) {
  if (skip(node.parentElement)) return;
  const raw = node.nodeValue;
  if (!raw || !/[A-Za-z]/.test(raw)) return;
  const fr = frText(raw);
  if (fr == null || fr === raw.trim()) return;
  ORIG.set(node, raw);
  const lead = raw.match(/^\s*/)[0], trail = raw.match(/\s*$/)[0];
  node.nodeValue = lead + fr + trail;
}
const ATTR_FR = { Up: 'Haut', Down: 'Bas', Left: 'Gauche', Right: 'Droite' };
function translateAttrs(el) {
  if (skip(el)) return;
  for (const a of ATTRS) {
    const v = el.getAttribute(a);
    if (!v) continue;
    const fr = ATTR_FR[v] ?? frText(v);
    if (fr == null || fr === v) continue;
    if (el.dataset[`en${a.replace(/-./, (x) => x[1].toUpperCase())}`] === undefined) el.dataset[`en${a.replace(/-./, (x) => x[1].toUpperCase())}`] = v;
    el.setAttribute(a, fr);
  }
}
export function translateTree(root) {
  if (!root) return;
  if (root.nodeType === 3) { translateText(root); return; }
  if (root.nodeType !== 1) return;
  translateAttrs(root);
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  let n;
  while ((n = w.nextNode())) { if (n.nodeType === 3) translateText(n); else translateAttrs(n); }
}
export function restoreEnglish(root = document.body) {
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  let n;
  while ((n = w.nextNode())) {
    if (n.nodeType === 3) { if (ORIG.has(n)) { n.nodeValue = ORIG.get(n); ORIG.delete(n); } continue; }
    for (const a of ATTRS) { const k = `en${a.replace(/-./, (x) => x[1].toUpperCase())}`; if (n.dataset?.[k] !== undefined) { n.setAttribute(a, n.dataset[k]); delete n.dataset[k]; } }
  }
}

// While French is on, text the code draws later is translated as it appears.
let observer = null;
export function watchFrench(on) {
  if (observer) { observer.disconnect(); observer = null; }
  if (!on) { restoreEnglish(); return; }
  translateTree(document.body);
  observer = new MutationObserver((list) => {
    for (const m of list) {
      if (m.type === 'characterData') translateText(m.target);
      else if (m.type === 'attributes') translateAttrs(m.target);
      else m.addedNodes.forEach(translateTree);
    }
  });
  observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ATTRS });
}
